    outB,hB,_=bstep_z(W,out.repeat(Bn,1),h.repeat(Bn,1,1),dt,e[None].repeat(Bn,1),u[None].repeat(Bn,1),M,ages,zfn=lambda c,e_,u_,i: Z)
    res=[]
    for k2 in range(k+1,len(B_)):
